CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, project_id TEXT NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE, path TEXT NOT NULL UNIQUE, trusted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE provider_connections (id TEXT PRIMARY KEY, config TEXT NOT NULL);
CREATE TABLE conversations (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, workspace_id TEXT REFERENCES workspaces(id) ON DELETE SET NULL, title TEXT NOT NULL, provider_id TEXT NOT NULL, model TEXT NOT NULL DEFAULT '', mode TEXT NOT NULL DEFAULT 'ask', updated_at TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE provider_sessions (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, provider_id TEXT NOT NULL, native_id TEXT, model TEXT NOT NULL, mode TEXT NOT NULL, capabilities TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX native_session_mapping ON provider_sessions(provider_id, native_id) WHERE native_id IS NOT NULL;
CREATE TABLE turns (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, session_id TEXT NOT NULL REFERENCES provider_sessions(id), request_id TEXT NOT NULL UNIQUE, status TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE messages (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, session_id TEXT NOT NULL REFERENCES provider_sessions(id), turn_id TEXT NOT NULL REFERENCES turns(id), role TEXT NOT NULL, text TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, provider_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE message_blocks (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, position INTEGER NOT NULL, type TEXT NOT NULL, content TEXT NOT NULL, UNIQUE(message_id, position));
CREATE TABLE events (seq INTEGER PRIMARY KEY AUTOINCREMENT, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, session_id TEXT NOT NULL REFERENCES provider_sessions(id), turn_id TEXT NOT NULL REFERENCES turns(id), type TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE interactions (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, session_id TEXT NOT NULL REFERENCES provider_sessions(id), turn_id TEXT NOT NULL REFERENCES turns(id), kind TEXT NOT NULL, title TEXT NOT NULL, detail TEXT NOT NULL, questions TEXT, status TEXT NOT NULL, response TEXT);
CREATE TABLE assets (id TEXT PRIMARY KEY, mime TEXT NOT NULL, type TEXT NOT NULL, size INTEGER NOT NULL, hash TEXT NOT NULL);
CREATE TABLE message_assets (message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id), PRIMARY KEY(message_id, asset_id));
CREATE TABLE terminal_profiles (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, preferences TEXT NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX conversation_recency ON conversations(project_id, updated_at DESC);
CREATE INDEX message_timeline ON messages(conversation_id, seq);
CREATE INDEX session_events ON events(session_id, seq);
CREATE INDEX conversation_events ON events(conversation_id, seq);
CREATE INDEX conversation_sessions ON provider_sessions(conversation_id, created_at);
